package com.jnapanam.sportszone.content.dto;import com.jnapanam.sportszone.content.model.*;import java.time.Instant;import java.util.UUID;public record EventResponse(UUID id,String slug,String title,String description,EventType eventType,String sportCode,String facilityName,Instant startsAt,Instant endsAt,String registrationUrl,String imageUrl,Integer capacity,ContentStatus status,boolean featured,int displayOrder){public static EventResponse from(PublicEvent e){return new EventResponse(e.getId(),e.getSlug(),e.getTitle(),e.getDescription(),e.getEventType(),e.getSport()==null?null:e.getSport().getCode(),e.getFacility()==null?null:e.getFacility().getName(),e.getStartsAt(),e.getEndsAt(),e.getRegistrationUrl(),e.getImageUrl(),e.getCapacity(),e.getStatus(),e.isFeatured(),e.getDisplayOrder());}}
